import {controller, target} from '@github/catalyst'
import './github/audit-log/audit-log-search-input'
import {remoteForm, type Kicker} from '@github/remote-form'
import {showGlobalError} from './github/behaviors/ajax-error'

@controller
class AuditLogExportFlashesElement extends HTMLElement {
  @target declare row: HTMLElement
  @target declare notice: HTMLElement
  @target declare warning: HTMLElement

  closeError() {
    this.row.hidden = true
    this.warning.hidden = true
  }

  closeNotice() {
    this.row.hidden = true
    if (this.notice) {
      this.notice.hidden = true
    }
  }
}

function fetchPoll(url: string, pollIntervalMs: number) {
  return new Promise((resolve, reject) => {
    setTimeout(async () => {
      const request = new Request(url)
      request.headers.append('X-Requested-With', 'XMLHttpRequest')
      const response = await fetch(request)
      if (response.status === 200) {
        // Resource is ready.
        resolve(response)
      } else if (response.status === 202) {
        // Resource isn't ready so we're gonna retry.
        resolve(fetchPoll(url, pollIntervalMs))
      } else {
        // Something unexpected happened.
        reject(response)
      }
    }, pollIntervalMs) // Poll the endpoint every intervalMs
  })
}

async function fetchTruncateStatus(url: string) {
  const request = new Request(url)
  request.headers.append('X-Requested-With', 'XMLHttpRequest')
  const resp = await fetch(request)
  const data = await resp.json()
  if (data.truncated) {
    const warning = document.getElementById('truncate-warning')!
    warning.hidden = false
  }
}

async function exportEvents(loadingClass: string, menuClass: string, wants: Kicker, pollIntervalMs: number) {
  const loadingState = document.querySelector<HTMLElement>(loadingClass)!
  const menu = document.querySelector<HTMLDetailsElement>(menuClass)!
  const flashContainer = document.querySelector<HTMLElement>('.js-flash-row')!
  const flashErrorMessage = document.querySelector<HTMLElement>('.js-error-flash-message')!
  const flashNoticeMessage = document.querySelector<HTMLElement>('.js-notice-flash-message')!
  const warning = document.getElementById('truncate-warning')!

  // Show/hide loading state. Set to `true` to hide menu and show loading state.
  function loading(toggle: boolean) {
    menu.hidden = toggle
    menu.open = false
    loadingState.hidden = !toggle
  }

  loading(true)
  if (warning != null) {
    warning.hidden = true
  }

  let response
  try {
    response = await wants.json()
  } catch (error) {
    loading(false)
    // @ts-expect-error catch blocks are bound to `unknown` so we need to validate the type before using it
    if (error.response.status === 429) {
      flashContainer.hidden = false
      flashErrorMessage.hidden = false
      flashNoticeMessage.hidden = true
    } else {
      showGlobalError()
    }

    return
  }

  const data = response.json

  try {
    flashContainer.hidden = false
    flashNoticeMessage.hidden = false
    flashErrorMessage.hidden = true
    await fetchPoll(data.status_url, pollIntervalMs)
  } catch {
    loading(false)
    showGlobalError()
    return
  }

  if (data.verify_url) {
    try {
      await fetchTruncateStatus(data.verify_url)
    } catch {
      loading(false)
      showGlobalError()
      return
    }
  }

  loading(false)
  window.location = data.export_url
}

remoteForm('.js-audit-log-export-form', async function (form, wants) {
  await exportEvents('.js-audit-log-exporting', '.js-audit-log-export-menu', wants, 2000)
})

remoteForm('.js-audit-log-git-event-export-form', async function (form, wants) {
  await exportEvents('.js-audit-log-git-event-exporting', '.js-audit-log-git-event-export-menu', wants, 10000)
})
